export function landRings(): [number, number][][] {
  return RINGS.map((s) => { let x = 0, y = 0; return s.split(" ").map((p) => { const [a, b] = p.split(",").map(Number); x += a!; y += b!; return [x / 20, y / 20] as [number, number]; }); });
}
